from pathlib import Path
import re

app_path=Path('app.js')
app=app_path.read_text(encoding='utf-8')

app=app.replace('<small>교전 주기</small>','<small>행동 주기</small>')
app=app.replace('setInterval(refresh,5000);','setInterval(refresh,2000);')

new_battle=r'''function battleEventState(e){const ev=e?.event_state||{},latest=(e?.battle_log||[])[0]||null,bs=e?.battle_state||{},active=bs?.active===true,ended=ev.type==='battle_end'||latest?.type==='battle-end';return {kind:active?'battle':ended?'result':'explore',event:ev,log:latest,bs}}
function battleHpSum(o){return Object.values(o||{}).reduce((a,v)=>a+Math.max(0,Number(v||0)),0)}
function battleSkillHtml(skills){if(!skills?.length)return '';return `<div class="battle-skill-banner">${skills.slice(0,4).map(s=>`<span><b>${esc(s.owner||'몬스터')}</b> ${esc(s.name||'고유 스킬')} <em>${s.attack?`${fmt(s.attack)}번째 공격`:'발동'}</em></span>`).join('')}</div>`}
function battleViewModel(e){const state=battleEventState(e),bs=state.bs,log=state.log||{},last=bs.lastAction||log||{},site=S.sites.find(x=>x.id===e.site_id),active=state.kind==='battle',result=state.kind==='result',showEnemy=active||result,enemy=bs.enemy||log.enemy||site?.enemy_names?.[0]||'용사',role=bs.enemyRole||log.enemyRole||'인간',party=partyOf(e),fallbackMax=party.reduce((a,m)=>a+monsterStats(m).hp,0),mmax=battleHpSum(bs.partyMaxHp)||fallbackMax,mhp=battleHpSum(bs.partyHp)||(active?mmax:fallbackMax),emax=Number(bs.enemyMaxHp||log.enemyMaxHp||1),ehp=Math.max(0,Number(bs.enemyHp??log.enemyHp??(result&&log.result==='win'?0:emax))),skills=Array.isArray(bs.skills)?bs.skills:Array.isArray(log.skills)?log.skills:[],deaths=Array.isArray(last.deaths)?last.deaths:[],turn=active?(bs.turn==='party'?'몬스터 턴':'인간 턴'):'',initiativePct=Math.round(Number(bs.initiativeChance||log.initiativeChance||0.5)*100),first=String(bs.initiative||log.initiative||'')==='party'?'몬스터 선공':'인간 선공';let typeText=e.phase||'탐색',resultText='인간 흔적과 전리품을 탐색 중',damageText='탐색 중',takenText='',badge=e.phase||'탐색';if(active){badge=turn;const t=last.type||'';if(t==='encounter'){typeText='상대 조우';resultText=`선공 확률 ${initiativePct}% · ${first}`;damageText=`몬스터 선공 ${initiativePct}%`}else if(last.side==='party'){typeText=turn;resultText='몬스터 측 공격';damageText=`가한 피해 ${fmt(last.damage||0)}`}else{typeText=turn;resultText=`${last.target||'몬스터'} 피격`;damageText='인간 측 공격';takenText=`받은 피해 ${fmt(last.damage||0)}`}}else if(result){badge='전투 종료';typeText=log.result==='win'?'박멸 성공':'전투 패배';resultText=log.result==='win'?`${enemy} 박멸 완료`:`${enemy}에게 패배`;damageText=`누적 피해 ${fmt(bs.damageDealt||log.damageDealt||0)}`;takenText=`받은 피해 ${fmt(bs.damageTaken||log.damageTaken||0)}`}if(deaths.length)takenText=`전투불능 · ${deaths.map(d=>`${d.name||'몬스터'} XP -${fmt(d.xpLost||0)}`).join(' · ')}`;return {state,bs,log,last,site,active,result,showEnemy,enemy,role,mhp,mmax,ehp,emax,skills,deaths,turn,initiativePct,first,typeText,resultText,damageText,takenText,badge}}
function battleLogHtml(e,m,site){const rows=(e.battle_log||[]).slice(0,16);if(!rows.length)return '<div class="combat-log-empty">첫 현장 기록을 기다리는 중...</div>';return rows.map(x=>{if(x.type==='explore')return `<div class="combat-log-row explore"><header><b>${esc(x.phase||'탐색')}</b><small>2초 행동</small></header><p>${esc(x.event||'현장을 살피는 중')}</p>${Number(x.loot)>0?`<em>전리품 +${fmt(x.loot)}</em>`:''}</div>`;if(x.type==='encounter'){const pct=Math.round(Number(x.initiativeChance||0.5)*100),first=x.initiative==='party'?'몬스터 선공':'인간 선공';return `<div class="combat-log-row encounter"><header><span><b>${esc(x.enemy||'용사')} 조우</b><small>${esc(x.enemyRole||'인간')}${x.boss?' · BOSS':''}</small></span><strong>선공 판정</strong></header><p>몬스터 측 선공 확률 <b>${pct}%</b> · ${first}</p></div>`}if(x.type==='battle-turn'){const party=x.side==='party',skills=Array.isArray(x.skills)?x.skills:[],deaths=Array.isArray(x.deaths)?x.deaths:[];return `<div class="combat-log-row battle-turn ${party?'party-turn':'enemy-turn'}"><header><span><b>${party?'몬스터 턴':'인간 턴'} · ${fmt(x.round||1)}R</b><small>${party?esc(x.enemy||'용사'):esc(x.target||'몬스터')} 대상</small></span><strong>${fmt(x.damage||0)} 피해</strong></header>${skills.length?`<div class="skill-proc-line">${skills.map(s=>`<span><b>${esc(s.owner||'몬스터')}</b> · ${esc(s.name||'고유 스킬')} · ${fmt(s.attack||0)}번째 공격</span>`).join('')}</div>`:''}${deaths.length?`<div class="combat-death-line">${deaths.map(d=>`<span><b>${esc(d.name||'몬스터')} 전투불능</b> · 현재 레벨 XP -${fmt(d.xpLost||0)}</span>`).join('')}</div>`:''}</div>`}if(x.type==='battle-end'){const skills=Array.isArray(x.skills)?x.skills:[],deaths=Array.isArray(x.deaths)?x.deaths:[];return `<div class="combat-log-row battle ${x.result||''}"><header><span><b>${esc(x.enemy||'용사')}</b><small>${esc(x.enemyRole||'인간')}${x.boss?' · BOSS':''}</small></span><strong>${x.result==='win'?'승리':'패배'}</strong></header><div class="combat-metrics"><span>가한 피해 <b>${fmt(x.damageDealt||0)}</b></span><span>받은 피해 <b>${fmt(x.damageTaken||0)}</b></span><span>라운드 <b>${fmt(x.round||1)}</b></span><span>전리품 <b>${fmt(x.loot||0)}</b></span></div>${skills.length?`<div class="skill-proc-line">${skills.map(s=>`<span><b>${esc(s.owner||'몬스터')}</b> · ${esc(s.name||'고유 스킬')}</span>`).join('')}</div>`:''}${deaths.length?`<div class="combat-death-line">${deaths.map(d=>`<span><b>${esc(d.name||'몬스터')} 전투불능</b> · 현재 레벨 XP -${fmt(d.xpLost||0)}</span>`).join('')}</div>`:''}</div>`}const enemy=esc(x.enemy||'용사'),role=esc(x.enemyRole||'인간'),result=x.result==='win'?'승리':'패배';return `<div class="combat-log-row battle ${x.result||''}"><header><span><b>${enemy}</b><small>${role}</small></span><strong>${result}</strong></header></div>`}).join('')}
function battlePartyHtml(e){const party=partyOf(e),bs=e?.battle_state||{},hp=bs.partyHp||{},mx=bs.partyMaxHp||{},tracked=Object.keys(mx).length>0;return party.slice(0,4).map((m,i)=>{const max=tracked?Number(mx[m.id]||monsterStats(m).hp):monsterStats(m).hp,cur=tracked?Math.max(0,Number(hp[m.id]||0)):max,dead=tracked&&cur<=0;return `<div class="battle-party-unit ${dead?'dead':''}" style="--party-index:${i}"><span>${charSvg(monsterAsset(m.family),'battle-sprite '+formClass(m))}</span><small>${esc(m.name)}</small>${tracked?`<em>${fmt(cur)}/${fmt(max)}</em>`:''}</div>`}).join('')}
function watchModal(expId){const e=S.expeditions.find(x=>x.id===expId);if(!e)return;const m=S.monsters.find(x=>x.id===e.monster_id),vm=battleViewModel(e),site=vm.site,ui=battleUi(e.site_id),meta=chapterMeta(e.site_id),mpct=Math.max(0,Math.min(100,vm.mmax?vm.mhp/vm.mmax*100:100)),epct=Math.max(0,Math.min(100,vm.emax?vm.ehp/vm.emax*100:100));watchingExpeditionId=expId;lastBattleVisualKey=null;modal(`<div class="battle-report-head"><div><h2>${esc(site?.name||'현장')}</h2><small>${siteCode(e.site_id)} · 2초 행동 턴 · 행동 ${fmt(e.exploration_count||0)}</small></div><button class="battle-report-close" data-action="close">×</button></div><div id="battleScene" class="battle-report-scene ${e.site_id} state-${vm.state.kind} ${vm.bs.boss?'boss':''} ${vm.log?.result||''}"><div class="battle-scene-top"><span class="battle-opcode">${siteCode(e.site_id)}</span><span id="liveStateBadge" class="battle-server-badge">${esc(vm.badge)}</span></div><div class="chapter-atmosphere"><span>${esc(meta.terrain)}</span><small>${esc(meta.weather)}</small></div><div class="battle-stage"><div class="battle-party-side"><div id="livePartyCluster" class="battle-party-cluster">${battlePartyHtml(e)}</div><span class="battle-hp"><i id="liveMonsterHp" style="width:${mpct}%"></i></span><small id="liveMonsterHpText" class="hp-text">${vm.active||vm.result?`${fmt(vm.mhp)}/${fmt(vm.mmax)}`:'이동/탐색 중'}</small></div><div class="battle-center-event"><div id="liveEncounterIcon" class="encounter-icon"><i class="encounter-pict ${vm.showEnemy?'combat':'explore'}"></i></div><b id="liveEncounterType">${esc(vm.typeText)}</b><small id="liveEncounterResult">${esc(vm.resultText)}</small></div><div id="liveEnemyActor" class="battle-actor enemy-actor ${vm.showEnemy?'':'hidden-contact'}"><div id="liveEnemySprite" class="actor-frame">${charSvg(enemyAsset(vm.enemy),'battle-sprite')}</div><span id="liveEnemyName" class="battle-name">${vm.showEnemy?`${esc(vm.enemy)} · ${esc(vm.role)}`:'접촉 없음'}</span><span class="battle-hp"><i id="liveEnemyHp" style="width:${vm.showEnemy?epct:0}%"></i></span><small id="liveEnemyHpText" class="hp-text">${vm.showEnemy?`${fmt(vm.ehp)}/${fmt(vm.emax)}`:'접촉 없음'}</small></div></div><div id="liveCombatFloats" class="battle-float-stack"><span id="liveDamageFloat">${esc(vm.damageText)}</span><span id="liveTakenFloat">${esc(vm.takenText)}</span></div><div id="liveSkillProc">${battleSkillHtml(vm.skills)}</div></div><div class="battle-report-body"><div id="liveAlert" class="battle-alert">${esc(e.event_state?.text||ui.alert)}</div><div class="battle-zone-copy"><b>행동 규칙</b><span>2초마다 수색·이동·전리품 회수·조우 또는 전투 턴이 1회 진행됩니다. 전투 중에는 몬스터 턴과 인간 턴이 번갈아 진행됩니다.</span></div><div class="battle-summary detailed"><div><small>현재 행동</small><b id="livePhase">${esc(vm.active?vm.turn:e.phase||'탐색')}</b></div><div><small>누적 박멸</small><b><span id="liveKills">${fmt(e.kills)}</span>명</b></div><div><small>회수 화물</small><b><span id="liveLoot">${lootCount(e)}</span>개</b></div><div><small>누적 치명타</small><b id="liveCrits">${vm.showEnemy?fmt(vm.bs.crits||0):'-'}</b></div><div><small>누적 회피</small><b id="liveDodges">${vm.showEnemy?fmt(vm.bs.dodges||0):'-'}</b></div><div><small>적 역할</small><b id="liveEnemyRole">${vm.showEnemy?esc(vm.role):'-'}</b></div></div><div class="combat-log-title"><b>행동 기록</b><small>서버 실제 2초 행동 데이터</small></div><div id="liveLog" class="combat-log">${battleLogHtml(e,m,site)}</div></div><div class="battle-report-actions"><button class="retreat" data-action="recall" data-id="${e.id}">현장 철수</button></div>`,'battle-report-sheet battle-sync-sheet');syncWatchPanel()}
'''
pattern=r"function battleEventState\(e\)\{.*?\nfunction itemModal"
if not re.search(pattern,app,re.S):
    raise SystemExit('battle UI block marker missing')
app=re.sub(pattern,new_battle+'\nfunction itemModal',app,count=1,flags=re.S)

new_sync=r'''function syncWatchPanel(){if(!watchingExpeditionId||!S)return;const e=S.expeditions.find(x=>x.id===watchingExpeditionId);if(!e)return;const m=S.monsters.find(x=>x.id===e.monster_id),vm=battleViewModel(e),scene=$('#battleScene'),key=String(e.event_state?.t||vm.log?.t||'');if(scene){scene.className=`battle-report-scene ${e.site_id} state-${vm.state.kind} ${vm.bs.boss?'boss':''} ${vm.log?.result||''}`;if(key&&key!==lastBattleVisualKey){lastBattleVisualKey=key;scene.classList.remove('event-pulse','skill-pulse');void scene.offsetWidth;scene.classList.add('event-pulse');if(vm.skills.length)scene.classList.add('skill-pulse')}}const text=(id,v)=>{const el=$(id);if(el)el.textContent=v};text('#liveKills',fmt(e.kills));text('#liveLoot',fmt(lootCount(e)));text('#liveEnemyName',vm.showEnemy?vm.enemy+' · '+vm.role:'접촉 없음');text('#liveAlert',e.event_state?.text||battleUi(e.site_id).alert);text('#livePhase',vm.active?vm.turn:e.phase||'탐색');text('#liveStateBadge',vm.badge);text('#liveEncounterType',vm.typeText);text('#liveEncounterResult',vm.resultText);text('#liveDamageFloat',vm.damageText);text('#liveTakenFloat',vm.takenText);text('#liveCrits',vm.showEnemy?fmt(vm.bs.crits||0):'-');text('#liveDodges',vm.showEnemy?fmt(vm.bs.dodges||0):'-');text('#liveEnemyRole',vm.showEnemy?vm.role:'-');const mh=$('#liveMonsterHp'),eh=$('#liveEnemyHp'),mht=$('#liveMonsterHpText'),eht=$('#liveEnemyHpText'),holder=$('#liveEnemySprite'),actor=$('#liveEnemyActor'),cluster=$('#livePartyCluster'),skill=$('#liveSkillProc'),logEl=$('#liveLog'),icon=$('#liveEncounterIcon .encounter-pict');if(icon)icon.className=`encounter-pict ${vm.showEnemy?'combat':'explore'}`;if(mh)mh.style.width=vm.active||vm.result?`${Math.max(0,Math.min(100,vm.mmax?vm.mhp/vm.mmax*100:100))}%`:'100%';if(eh)eh.style.width=vm.showEnemy?`${Math.max(0,Math.min(100,vm.emax?vm.ehp/vm.emax*100:100))}%`:'0%';if(mht)mht.textContent=vm.active||vm.result?`${fmt(vm.mhp)}/${fmt(vm.mmax)}`:'이동/탐색 중';if(eht)eht.textContent=vm.showEnemy?`${fmt(vm.ehp)}/${fmt(vm.emax)}`:'접촉 없음';if(actor)actor.classList.toggle('hidden-contact',!vm.showEnemy);if(holder&&vm.showEnemy){const u=holder.querySelector('use');if(u)u.setAttribute('href',`assets/characters.svg#${enemyAsset(vm.enemy)}`)}if(cluster)cluster.innerHTML=battlePartyHtml(e);if(skill)skill.innerHTML=battleSkillHtml(vm.skills);if(logEl&&m)logEl.innerHTML=battleLogHtml(e,m,vm.site)}
'''
pattern=r"function syncWatchPanel\(\)\{.*?\n\nfunction updateEconomyProgress"
if not re.search(pattern,app,re.S):
    raise SystemExit('sync watch marker missing')
app=re.sub(pattern,new_sync+'\nfunction updateEconomyProgress',app,count=1,flags=re.S)

app_path.write_text(app,encoding='utf-8')

css_path=Path('app.css')
css=css_path.read_text(encoding='utf-8')
css += r'''

/* v0.12.4 persistent 2-second turn combat */
.battle-party-unit{position:relative}.battle-party-unit>em{display:block;margin-top:1px;font:700 7px monospace;color:#aab6ad}.battle-party-unit.dead{opacity:.34;filter:grayscale(1)}.battle-party-unit.dead:after{content:'DOWN';position:absolute;inset:20px 2px auto;background:#3a1717;color:#f2a0a0;border:1px solid #7c3434;font:800 7px monospace;text-align:center;padding:2px}.combat-log-row.encounter{border-color:#6e5d39;background:#1c1a12}.combat-log-row.encounter strong{color:#efbb78}.combat-log-row.battle-turn{border-left:3px solid #55675a}.combat-log-row.battle-turn.party-turn{border-left-color:#7ea36e}.combat-log-row.battle-turn.enemy-turn{border-left-color:#a65d55}.combat-death-line{margin-top:5px;padding:5px 6px;border:1px solid #733939;background:#281515;color:#ef9b95;font-size:8px;line-height:1.5}.combat-death-line span{display:block}.battle-report-scene.state-battle .battle-server-badge{animation:turnPulse 1s steps(2,end) infinite}.battle-report-scene.state-result .battle-server-badge{background:#2b2520;color:#efbb78}@keyframes turnPulse{50%{filter:brightness(1.35)}}
'''
css_path.write_text(css,encoding='utf-8')

index_path=Path('index.html')
html=index_path.read_text(encoding='utf-8')
html=html.replace('v0.12.3','v0.12.4').replace('0123a','0124a')
index_path.write_text(html,encoding='utf-8')
